def longestSubarray(nums: list[int]) -> int:
    max_val = max(nums)
    max_len = curr_len = 0
    for x in nums:
        if x == max_val:
            curr_len += 1
            max_len = max(max_len, curr_len)
        else:
            curr_len = 0
    return max_len

